suspend fun loadUser(id: UserId): Either<DomainError, User> = either {
    val user = repo.find(id).bind()
    val address = addressRepo.find(user.addressId).bind()
    user.copy(address = address)
}

loadUser(id).fold(
    { error -> render(error) },
